<script lang="ts">import CalgaryMap from '../../lib/CalgaryMap.svelte';let{data}=$props();const format=(v:string)=>{const d=new Date(v);return `${d.toLocaleDateString()} ${d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`}</script>
